import (
	"reflect"
	"testing"
)

func eq(t *testing.T, name, got, want string) {
	t.Helper()
	if got != want {
		t.Errorf("%s:\ngot:  %q\nwant: %q", name, got, want)
	}
}

func TestSpecExample(t *testing.T) {
	in := "# Title #\n\nSome *emphasis* and **strong** text\nwith `code` and a [link](http://x.io \"T\").\n\n- one\n- two\n  - nested\n3. three\n"
	want := "<h1>Title</h1>\n" +
		"<p>Some <em>emphasis</em> and <strong>strong</strong> text\nwith <code>code</code> and a <a href=\"http://x.io\" title=\"T\">link</a>.</p>\n" +
		"<ul>\n<li>one</li>\n<li>two\n<ul>\n<li>nested</li>\n</ul>\n</li>\n</ul>\n" +
		"<ol start=\"3\">\n<li>three</li>\n</ol>\n"
	eq(t, "spec example", ToHTML(in), want)
}

func TestHeadings(t *testing.T) {
	cases := []struct{ in, want string }{
		{"# ", "<h1></h1>\n"},
		{"#", "<h1></h1>\n"},
		{"# Title #", "<h1>Title</h1>\n"},
		{"# Title  ##  ", "<h1>Title</h1>\n"},
		{"# Title##", "<h1>Title##</h1>\n"},
		{"## Two", "<h2>Two</h2>\n"},
		{"###### Six", "<h6>Six</h6>\n"},
		{"####### Seven", "<p>####### Seven</p>\n"},
		{"#foo", "<p>#foo</p>\n"},
		{"#*em*# ", "<h1>*em*#</h1>\n"},
	}
	for _, c := range cases {
		eq(t, "heading "+c.in, ToHTML(c.in), c.want)
	}
}

func TestHR(t *testing.T) {
	cases := []struct{ in, want string }{
		{"---", "<hr />\n"},
		{"----", "<hr />\n"},
		{"***", "<hr />\n"},
		{"___", "<hr />\n"},
		{"-", "<p>-</p>\n"},
		{"**", "<p>**</p>\n"},
		{"- - -", "<p>- - -</p>\n"},
	}
	for _, c := range cases {
		eq(t, "hr "+c.in, ToHTML(c.in), c.want)
	}
}

func TestFence(t *testing.T) {
	cases := []struct{ in, want string }{
		{"```\na < b\n```", "<pre><code>a &lt; b\n</code></pre>\n"},
		{"```go\na := 1\n```", "<pre><code class=\"language-go\">a := 1\n</code></pre>\n"},
		{"```\na\nb", "<pre><code>a\nb\n</code></pre>\n"},
		{"```\n```", "<pre><code></code></pre>\n"},
		{"```\nx\n```\nafter", "<pre><code>x\n</code></pre>\n<p>after</p>\n"},
	}
	for _, c := range cases {
		eq(t, "fence", ToHTML(c.in), c.want)
	}
}

func TestBlockquote(t *testing.T) {
	cases := []struct{ in, want string }{
		{"> hello", "<blockquote>\n<p>hello</p>\n</blockquote>\n"},
		{"> hello\n> world", "<blockquote>\n<p>hello\nworld</p>\n</blockquote>\n"},
		{"> a\n>\n> b", "<blockquote>\n<p>a</p>\n<p>b</p>\n</blockquote>\n"},
		{"> - x\n> - y", "<blockquote>\n<ul>\n<li>x</li>\n<li>y</li>\n</ul>\n</blockquote>\n"},
		{">> x", "<blockquote>\n<blockquote>\n<p>x</p>\n</blockquote>\n</blockquote>\n"},
		{"> x", "<blockquote>\n<p>x</p>\n</blockquote>\n"},
	}
	for _, c := range cases {
		eq(t, "blockquote "+c.in, ToHTML(c.in), c.want)
	}
}

func TestLists(t *testing.T) {
	cases := []struct{ in, want string }{
		{"- a\n- b", "<ul>\n<li>a</li>\n<li>b</li>\n</ul>\n"},
		{"1. a\n2. b", "<ol>\n<li>a</li>\n<li>b</li>\n</ol>\n"},
		{"3. a\n4. b", "<ol start=\"3\">\n<li>a</li>\n<li>b</li>\n</ol>\n"},
		{"* a\n+ b", "<ul>\n<li>a</li>\n<li>b</li>\n</ul>\n"},
		{"- a\n1. b", "<ul>\n<li>a</li>\n</ul>\n<ol>\n<li>b</li>\n</ol>\n"},
		{"1. a\n- b", "<ol>\n<li>a</li>\n</ol>\n<ul>\n<li>b</li>\n</ul>\n"},
		{"- a\n  cont", "<ul>\n<li>a\ncont</li>\n</ul>\n"},
		{"- a\n  - b\n  - c", "<ul>\n<li>a\n<ul>\n<li>b</li>\n<li>c</li>\n</ul>\n</li>\n</ul>\n"},
		{"- a\n  - b\n  cont", "<ul>\n<li>a\n<ul>\n<li>b</li>\n</ul>\ncont</li>\n</ul>\n"},
	}
	for _, c := range cases {
		eq(t, "list "+c.in, ToHTML(c.in), c.want)
	}
}

func TestParagraph(t *testing.T) {
	cases := []struct{ in, want string }{
		{"a\nb", "<p>a\nb</p>\n"},
		{"a\n\nb", "<p>a</p>\n<p>b</p>\n"},
		{"a\n# h", "<p>a</p>\n<h1>h</h1>\n"},
		{"a\n---", "<p>a</p>\n<hr />\n"},
	}
	for _, c := range cases {
		eq(t, "para "+c.in, ToHTML(c.in), c.want)
	}
}

func TestEmphasis(t *testing.T) {
	cases := []struct{ in, want string }{
		{"*a*", "<p><em>a</em></p>\n"},
		{"**a**", "<p><strong>a</strong></p>\n"},
		{"_a_", "<p><em>a</em></p>\n"},
		{"__a__", "<p><strong>a</strong></p>\n"},
		{"snake_case_name", "<p>snake_case_name</p>\n"},
		{"a*b*c", "<p>a<em>b</em>c</p>\n"},
		{"* a*", "<p>* a*</p>\n"},
		{"*a *", "<p><em>a</em> *</p>\n"},
		{"**a *b* c**", "<p><strong>a <em>b</em> c</strong></p>\n"},
		{"*a **b** c*", "<p><em>a <strong>b</strong> c</em></p>\n"},
		{"***a***", "<p><strong>a</strong></p>\n"},
		{"_a_b_c_", "<p>_a_b_c_</p>\n"},
	}
	for _, c := range cases {
		eq(t, "em "+c.in, ToHTML(c.in), c.want)
	}
}

func TestCodeSpan(t *testing.T) {
	cases := []struct{ in, want string }{
		{"`a<b`", "<p><code>a&lt;b</code></p>\n"},
		{"` a b `", "<p><code>a b</code></p>\n"},
		{"``a`b``", "<p><code>a`b</code></p>\n"},
		{"`unmatched", "<p>`unmatched</p>\n"},
		{"`a`*b*`c`", "<p><code>a</code><em>b</em><code>c</code></p>\n"},
	}
	for _, c := range cases {
		eq(t, "code "+c.in, ToHTML(c.in), c.want)
	}
}

func TestLinks(t *testing.T) {
	cases := []struct{ in, want string }{
		{"[t](http://x)", "<p><a href=\"http://x\">t</a></p>\n"},
		{"[t](http://x \"Ti\")", "<p><a href=\"http://x\" title=\"Ti\">t</a></p>\n"},
		{"[t](http://x \"a b\")", "<p><a href=\"http://x\" title=\"a b\">t</a></p>\n"},
		{"[t](bad url)", "<p>[t](bad url)</p>\n"},
		{"[t]", "<p>[t]</p>\n"},
		{"[t](http://x", "<p>[t](http://x</p>\n"},
		{"[*e*](u)", "<p><a href=\"u\"><em>e</em></a></p>\n"},
		{"[a b](u)", "<p><a href=\"u\">a b</a></p>\n"},
	}
	for _, c := range cases {
		eq(t, "link "+c.in, ToHTML(c.in), c.want)
	}
}

func TestAutolink(t *testing.T) {
	cases := []struct{ in, want string }{
		{"<http://x>", "<p><a href=\"http://x\">http://x</a></p>\n"},
		{"<https://x.io/p?a=1>", "<p><a href=\"https://x.io/p?a=1\">https://x.io/p?a=1</a></p>\n"},
		{"<http://a b>", "<p>&lt;http://a b&gt;</p>\n"},
		{"<ftp://x>", "<p>&lt;ftp://x&gt;</p>\n"},
	}
	for _, c := range cases {
		eq(t, "autolink "+c.in, ToHTML(c.in), c.want)
	}
}

func TestEscapes(t *testing.T) {
	cases := []struct{ in, want string }{
		{`a & b`, "<p>a &amp; b</p>\n"},
		{`a < b`, "<p>a &lt; b</p>\n"},
		{`a > b`, "<p>a &gt; b</p>\n"},
		{`a " b`, "<p>a &quot; b</p>\n"},
		{`a \* b`, "<p>a * b</p>\n"},
		{`a \& b`, "<p>a &amp; b</p>\n"},
		{`a \ b`, "<p>a \\ b</p>\n"},
		{`a \n b`, "<p>a \n b</p>\n"},
	}
	for _, c := range cases {
		eq(t, "esc "+c.in, ToHTML(c.in), c.want)
	}
}

func TestHardBreak(t *testing.T) {
	cases := []struct{ in, want string }{
		{"a  \nb", "<p>a<br />\nb</p>\n"},
		{"a \nb", "<p>a\nb</p>\n"},
		{"a\\ \nb", "<p>a<br />\nb</p>\n"},
		{"a\\\nb", "<p>a<br />\nb</p>\n"},
		{"a  ", "<p>a</p>\n"},
		{"a\\\nb  \nc", "<p>a<br />\nb<br />\nc</p>\n"},
	}
	for _, c := range cases {
		eq(t, "break "+c.in, ToHTML(c.in), c.want)
	}
}

func TestCombined(t *testing.T) {
	cases := []struct{ in, want string }{
		{"# T\n\ntext  \nmore\n\n> q\n\n- i\n\n```\nx\n```\n\n---",
			"<h1>T</h1>\n<p>text<br />\nmore</p>\n<blockquote>\n<p>q</p>\n</blockquote>\n<ul>\n<li>i</li>\n</ul>\n<pre><code>x\n</code></pre>\n<hr />\n"},
		{"a\\\r\nb\r\n", "<p>a<br />\nb</p>\n"},
	}
	for _, c := range cases {
		eq(t, "combined", ToHTML(c.in), c.want)
	}
}

